#pragma once
// Codegen drivers: proto/*.yaml -> C++ codecs + sim client;
// api/*.yaml -> C++ bindings + engine.d.luau. Generated files carry a header
// and are never edited by hand.
#include <string>
#include <vector>

namespace tooling::codegen {

struct GeneratedFile { std::string path; std::string content; };

inline constexpr const char* kGeneratedHeader =
    "// GENERATED by rathena-codegen. DO NOT EDIT.\n";

std::vector<GeneratedFile> generate_codecs(const std::string& proto_dir);  // stub
std::vector<GeneratedFile> generate_api(const std::string& api_dir);       // stub
// Verifies that on-disk generated files equal what the generator emits now.
bool check_up_to_date(const std::vector<GeneratedFile>& files, const std::string& out_dir);  // stub

}  // namespace tooling::codegen
